if(!$staff):
$publicProjects=projectList(true);
?>
<section class="panel"><h2>Suggestions &amp; Comments</h2><p>Share a project idea, a youth need, or a comment about an approved project. Your message will be sent privately to the SK Admin and Chairperson for review.</p><p class="note">Do not include passwords, bank details or sensitive personal information. This box is not monitored for emergencies. Messages are not published automatically.</p><form method="post"><?php actionFields('submit_feedback'); ?><div class="grid two"><?php selectField('Message Type','feedback_type',['Suggestion'=>'Project Suggestion','Comment'=>'Comment']);selectField('Related Public Project (optional)','project_id',[''=>'General suggestion / comment']+array_column($publicProjects,'title','id'),'',false); ?></div><?php field('Your Name (optional)','display_name',$user['name']??'','text',false,'maxlength="100"');field('Subject','subject','','text',true,'maxlength="150"');textarea('Your Suggestion / Comment','message','',true,2000); ?><p class="muted">Maximum 2,000 characters. Up to five messages per ten minutes from the same connection.</p><button>Send to SK Team</button></form></section>
<?php else:
allow(['admin','chairperson']);$status=is_string($_GET['status']??null)?$_GET['status']:'';if(!in_array($status,['','New','Reviewed','Archived'],true))$status='';
$messages=rows('SELECT f.*,p.title project_title,u.name reviewer FROM public_feedback f LEFT JOIN projects p ON p.id=f.project_id LEFT JOIN users u ON u.id=f.reviewed_by'.($status!==''?' WHERE f.status=?':'').' ORDER BY f.id DESC LIMIT 200',$status!==''?[$status]:[]);
?>
<section class="panel"><h2>Community Feedback Inbox</h2><p class="muted">Private Youth/Resident suggestions and comments. Review messages before using them in planning; they are not automatically verified needs. Guest names are self-reported and are not verified identities.</p><form method="get" class="filters"><input type="hidden" name="page" value="feedback"><?php selectField('Status','status',[''=>'All Messages','New'=>'New','Reviewed'=>'Reviewed','Archived'=>'Archived'],$status,false); ?><button>Apply</button><a class="button secondary" href="<?= e(url('feedback')) ?>">Reset</a></form><div class="table-wrap" tabindex="0" role="region" aria-label="Community feedback records"><table><thead><tr><th>Date</th><th>Type / Subject</th><th>From</th><th>Status</th><th>Message / Review</th></tr></thead><tbody><?php foreach($messages as $message): ?><tr><td><?= e($message['created_at']) ?></td><td><?= badge($message['type']) ?><p><?= e($message['subject']) ?></p><?php if($message['project_title']): ?><small>Related project: <?= e($message['project_title']) ?></small><?php endif ?></td><td><?= e($message['display_name']) ?><br><small><?= $message['user_id']?'Signed-in resident':'Guest submission' ?></small></td><td><?= badge($message['status']) ?></td><td><details><summary>Read / Review</summary><p class="prewrap"><?= e($message['message']) ?></p><?php if($message['reviewer']): ?><p class="muted">Reviewed by <?= e($message['reviewer']) ?> · <?= e($message['reviewed_at']) ?></p><?php endif ?><form method="post"><?php actionFields('review_feedback'); ?><input type="hidden" name="id" value="<?= e($message['id']) ?>"><?php selectField('Review Status','status',['New'=>'New','Reviewed'=>'Reviewed','Archived'=>'Archived'],$message['status']);textarea('Internal Notes','review_notes',$message['review_notes']??'',false,2000); ?><button class="small">Save Review</button></form></details></td></tr><?php endforeach;if(!$messages)emptyRow(5,'No messages match this filter.'); ?></tbody></table></div><p class="muted">Showing up to 200 latest messages. Filter by status to review pending feedback.</p></section>
